#include <iostream>
#include <string>
using namespace std;

// Correct inheritance - all 3 gates pass
class Shape {
protected:
    string colour;
public:
    virtual double area() = 0;
    string describe() {                // shared code all shapes use
        return colour + " shape, area=" + to_string(area());
    }
};

class Circle : public Shape {
    double r;
public:
    Circle(double r) : r(r) {}
    double area() override { return 3.14159 * r * r; }
};

class Rectangle : public Shape {
    double w, h;
public:
    Rectangle(double w, double h) : w(w), h(h) {}
    double area() override { return w * h; }
};

int main() {
    Shape* s = new Circle(5.0);
    cout << s->describe() << endl;   // calls shared describe() + Circle.area()
    delete s;
    return 0;
}

