#include <iostream>
using namespace std;

// Interfaces (behaviours)
class FlyBehaviour  { public: virtual void fly()  = 0; virtual ~FlyBehaviour()  {} };
class SwimBehaviour { public: virtual void swim() = 0; virtual ~SwimBehaviour() {} };

class FlapWings   : public FlyBehaviour  { public: void fly()  override { cout << "Flapping wings" << endl; } };
class NoFly       : public FlyBehaviour  { public: void fly()  override { cout << "Can't fly" << endl; } };
class NaturalSwim : public SwimBehaviour { public: void swim() override { cout << "Swimming" << endl; } };

// Composition - Duck needs to fly AND swim
class Duck {
    FlyBehaviour*  fly;
    SwimBehaviour* swim;
public:
    Duck(FlyBehaviour* fly, SwimBehaviour* swim) : fly(fly), swim(swim) {}

    void doFly()  { fly->fly(); }
    void doSwim() { swim->swim(); }

    // Behaviour can change at runtime - duck gets injured
    void setFly(FlyBehaviour* fb) { fly = fb; }
};

int main() {
    // Different ducks, different behaviours - no hierarchy
    Duck mallard(new FlapWings(), new NaturalSwim());
    Duck rubberDuck(new NoFly(), new NaturalSwim());

    // Mallard gets injured - swap at runtime
    mallard.setFly(new NoFly());
    mallard.doFly();
    return 0;
}

