#include <iostream>
using namespace std;

class Rectangle {
protected:
    int width, height;
public:
    virtual void setWidth(int w)  { width  = w; }
    virtual void setHeight(int h) { height = h; }
    int getWidth()  { return width; }
    int getHeight() { return height; }
};

class Square : public Rectangle {
public:
    // Must keep width == height - overrides both setters
    void setWidth(int w) override  { width = height = w; }
    void setHeight(int h) override { width = height = h; }
};

// This works for Rectangle but BREAKS for Square:
void testArea(Rectangle& r) {
    r.setWidth(5);
    r.setHeight(10);
    cout << (r.getWidth() * r.getHeight()) << endl;  // FAILS for Square: gives 100 not 50
}

int main() {
    Rectangle rect;
    testArea(rect);   // 50 - correct

    Square sq;
    testArea(sq);     // 100 - broken contract!
    return 0;
}

